descriptor.templateCss:
/* SUNKUU 360 — Portal de Flota · CSS v3
   Tokens: --navy #00008C · --teal #00EBC8 · --bg #EBF0F7 · --brd #D4E0EE
   Cambios v3: variables :root, hardcoded→tokens, badges normalizados, uppercase auditado */

#pf-root {
  --navy: #00008C;
  --teal: #00EBC8;
  --bg:   #EBF0F7;
  --surf: #FFFFFF;
  --pri:  #0D1B2E;
  --sec:  #5A6E8A;
  --ter:  #96AABF;
  --brd:  #D4E0EE;
  --pos:  #10B981;
  --neg:  #EF4444;
  --warn: #F59E0B;
  --ind:  #6366F1;
  --shd:  0 1px 3px rgba(13,27,46,.06), 0 8px 28px rgba(13,27,46,.08);
}

*{box-sizing:border-box;margin:0;padding:0}
#pf-root{font-family:system-ui,-apple-system,'Segoe UI',sans-serif;background:var(--bg);height:100%;display:flex;flex-direction:column;transition:background .3s;overflow:hidden}

/* Cambio de fondo por capa */
#pf-root.l0{background:#E3EAF4}
#pf-root.l1{background:var(--bg)}

/* ── HEADER ──────────────────────────────────────────────── */
#pf-hdr{background:linear-gradient(135deg,var(--navy) 0%,#0a0aaa 50%,#000f72 100%);box-shadow:0 2px 14px rgba(0,0,0,.32);flex-shrink:0;z-index:20}
.pf-hi{max-width:1440px;margin:0 auto;padding:0 24px;height:56px;display:flex;align-items:center;justify-content:space-between}
.pf-hl{display:flex;align-items:center;gap:14px}
.pf-logo{display:flex;align-items:center;gap:9px;font-weight:800;font-size:17px;letter-spacing:-.01em;color:white}
.brand-img{height:22px;width:auto;display:block}
.ls{font-weight:400;font-size:10px;color:rgba(255,255,255,.8);margin-left:4px;letter-spacing:.05em}

/* Breadcrumb */
#pf-bc{display:flex;align-items:center;gap:10px}
#btn-bc{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:8px;padding:6px 11px;cursor:pointer;color:rgba(255,255,255,.7);font-size:11px;font-weight:600;font-family:inherit;transition:all .15s}
#btn-bc:hover{background:rgba(255,255,255,.14);color:white}
.bc-sep{width:1px;height:18px;background:rgba(255,255,255,.2)}
.bc-avatar{width:24px;height:24px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:white;flex-shrink:0}
.bc-name{font-size:13px;font-weight:700;color:white}

/* Header right */
.pf-hr{display:flex;align-items:center;gap:12px}
.pf-online{display:flex;align-items:center;gap:6px}
.pf-odot{width:7px;height:7px;border-radius:50%;background:var(--pos);box-shadow:0 0 6px rgba(16,185,129,.7)}
#pf-online-txt{font-size:11px;color:rgba(255,255,255,.6)}
.pf-vsep{width:1px;height:22px;background:rgba(255,255,255,.1)}
.pf-user{display:flex;align-items:center;gap:9px}
.pf-uav{width:30px;height:30px;border-radius:50%;background:rgba(0,235,200,.2);border:1px solid rgba(0,235,200,.35);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:var(--teal);flex-shrink:0}
.pf-uname{font-size:11px;font-weight:600;color:white;line-height:1.2}
.pf-urole{font-size:9px;color:rgba(255,255,255,.35);line-height:1.2}

/* ── BODY ────────────────────────────────────────────────── */
#pf-body{padding:20px 24px 80px;overflow-y:auto}

/* ── ALERT RIBBON ────────────────────────────────────────── */
#pf-alert{background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.22);border-radius:12px;padding:12px 18px;margin-bottom:16px;display:flex;align-items:center;gap:10px}
.pal-dot{width:8px;height:8px;border-radius:50%;background:var(--neg);box-shadow:0 0 6px rgba(239,68,68,.7);flex-shrink:0;animation:pulse-a 1.8s ease-in-out infinite}
@keyframes pulse-a{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,.5)}50%{box-shadow:0 0 0 5px rgba(239,68,68,0)}}
#pf-alert-txt{font-size:12px;font-weight:600;color:#991B1B;flex:1}
.pal-btn{margin-left:auto;font-size:10px;font-weight:700;color:var(--neg);background:rgba(239,68,68,.12);border:1px solid rgba(239,68,68,.28);border-radius:6px;padding:4px 10px;cursor:pointer;flex-shrink:0}

/* ── KPI BAR ─────────────────────────────────────────────── */
#pf-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:28px}
.pf-kpi{background:var(--surf);border-radius:16px;border:1px solid var(--brd);border-top:3px solid var(--navy);box-shadow:var(--shd);padding:18px 20px;transition:border-top-color .3s}
.pf-kpi.accent{border-top-color:var(--teal)}
/* UPPERCASE solo en labels de texto puro — sin unidades físicas */
.pk-lbl{font-size:10px;font-weight:700;color:var(--ter);letter-spacing:.06em;text-transform:uppercase;margin-bottom:10px}
.pk-val{display:flex;align-items:baseline;gap:7px;flex-wrap:wrap}
.pk-val>span:first-child{font-size:30px;font-weight:800;color:var(--pri);letter-spacing:-.04em;font-variant-numeric:tabular-nums;line-height:1}
.pk-suf{font-size:11px;font-weight:600;color:var(--navy)}
.pk-val.alert-val>span:first-child{color:var(--neg)}
.pk-val.warn-val  { color: #F59E0B; }
.pk-val.ok-val    { color: var(--teal, #00EBC8); }
.pk-val.ok-val>span:first-child{color:var(--pos)}
.pk-val.warn-val  { color: #F59E0B; }
.pk-val.ok-val    { color: var(--teal); }

/* ── CAPA 0: HEADER ──────────────────────────────────────── */
.l0-hdr{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:10px}
.l0-title{font-size:20px;font-weight:800;color:var(--pri);letter-spacing:-.02em}
.l0-sub{font-size:12px;color:var(--ter);margin-top:4px}
.l0-total-badge{background:var(--surf);border:1px solid var(--brd);border-radius:8px;padding:8px 14px;font-size:11px;font-weight:600;color:var(--sec);align-self:center;white-space:nowrap}
.l0-total-badge span{font-size:14px;font-weight:800;color:var(--navy);margin-right:3px}

/* ── CAPA 0: FILAS DE CLIENTE ────────────────────────────── */
#client-list{display:flex;flex-direction:column;gap:10px}

.cl-row{background:var(--surf);border:1px solid var(--brd);border-radius:14px;padding:0;cursor:pointer;transition:all .2s;overflow:hidden;display:flex;align-items:stretch}
.cl-row:hover{border-color:rgba(0,235,200,.45);box-shadow:0 4px 16px rgba(0,0,0,.08);transform:translateY(-1px)}
.cl-row:hover .cr-go{color:var(--teal)}

/* Barra lateral coloreada por salud */
.cl-row-bar{width:4px;flex-shrink:0;background:var(--pos);transition:background .3s}
.cl-row-bar.atencion{background:var(--warn)}
.cl-row-bar.alerta{background:var(--neg)}

.cl-row-inner{flex:1;padding:16px 20px;display:grid;grid-template-columns:auto 1fr auto auto auto auto;align-items:center;gap:20px}

/* Identity */
.cr-id{display:flex;align-items:center;gap:12px;min-width:200px}
.cr-av{width:42px;height:42px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:800;color:white;flex-shrink:0}
.cr-name{font-size:14px;font-weight:800;color:var(--pri)}
.cr-loc{font-size:10px;color:var(--ter);margin-top:3px}

/* ── BADGES DE ESTADO — normalizados contra Template 3EM ── */
/* Padding, font-size, border-radius, letter-spacing unificados */
.cr-health{flex-shrink:0}
.hb{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:20px;font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;white-space:nowrap}
.hb.normal  {background:rgba(16,185,129,.1);color:#065F46;border:1px solid rgba(16,185,129,.22)}
.hb.atencion{background:rgba(245,158,11,.1);color:#92400E;border:1px solid rgba(245,158,11,.22)}
.hb.alerta  {background:rgba(239,68,68,.1);color:#991B1B;border:1px solid rgba(239,68,68,.22);animation:pulse-hb 2s ease-in-out infinite}
.hb.offline {background:rgba(90,110,138,.1);color:var(--sec);border:1px solid rgba(90,110,138,.2)}
.hb.sin-datos{background:rgba(150,170,191,.1);color:var(--ter);border:1px solid rgba(150,170,191,.2)}
@keyframes pulse-hb{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,.3)}50%{box-shadow:0 0 0 4px rgba(239,68,68,0)}}

/* Stats en fila */
.cr-stats{display:flex;gap:32px;align-items:center}
.cr-stat{text-align:right}
.cr-stat-v{font-size:16px;font-weight:800;color:var(--pri);font-variant-numeric:tabular-nums;line-height:1}
.cr-stat-l{font-size:9px;color:var(--ter);margin-top:3px;white-space:nowrap}

/* Trend */
.cr-trend-wrap{flex-shrink:0;text-align:center}
.cr-trend-val{font-size:13px;font-weight:700;line-height:1}
.cr-trend-lbl{font-size:9px;color:var(--ter);margin-top:3px}

/* Meta + action */
.cr-meta{display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0}
.cr-upd{font-size:10px;color:var(--ter);white-space:nowrap}
.cr-go{font-size:11px;font-weight:700;color:var(--navy);white-space:nowrap;transition:color .15s}

/* Placeholder row */
.cl-row.placeholder{cursor:default;background:rgba(0,0,140,.02);border:2px dashed rgba(0,0,140,.15)}
.cl-row.placeholder:hover{transform:none;box-shadow:none;border-color:rgba(0,0,140,.15)}
.cl-ph-inner{flex:1;padding:20px 24px;display:flex;align-items:center;gap:16px}
.cl-ph-icon{width:42px;height:42px;border-radius:10px;background:rgba(0,0,140,.07);border:2px dashed rgba(0,0,140,.18);display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:200;color:var(--navy);flex-shrink:0}
.cl-ph-name{font-size:14px;font-weight:700;color:var(--navy)}
.cl-ph-sub{font-size:11px;color:var(--ter);margin-top:2px}
.cl-ph-badge{margin-left:auto;background:rgba(0,235,200,.08);border:1px solid rgba(0,235,200,.2);border-radius:6px;padding:5px 12px;font-size:9px;font-weight:800;color:var(--navy);letter-spacing:.08em;white-space:nowrap}

/* ── CAPA 1: CLIENT HERO ─────────────────────────────────── */
.ch-hero{background:var(--surf);border-radius:18px;border:1px solid var(--brd);box-shadow:var(--shd);padding:24px 28px;margin-bottom:28px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;border-left:5px solid var(--navy);transition:border-left-color .3s}
.ch-left{display:flex;align-items:center;gap:18px}
.ch-avatar{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:800;color:white;flex-shrink:0}
.ch-name{font-size:22px;font-weight:800;color:var(--pri);letter-spacing:-.02em;line-height:1}
.ch-meta{display:flex;align-items:center;gap:8px;margin-top:6px;flex-wrap:wrap}
.ch-meta>span{font-size:11px;color:var(--ter)}
.chm-sep{color:var(--brd)!important}
.ch-email{font-size:11px;color:var(--ter)}
.ch-kpis{display:flex;align-items:center;gap:0;border:1px solid var(--brd);border-radius:12px;overflow:hidden;flex-wrap:wrap}
.ch-kpi{padding:14px 22px;text-align:center}
/* Label KPI hero: texto puro, uppercase ok */
.chk-lbl{font-size:9px;font-weight:600;color:var(--ter);text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px}
.chk-val{font-size:20px;font-weight:800;color:var(--pri);font-variant-numeric:tabular-nums;line-height:1}
.chk-unit{font-size:11px;font-weight:600;color:var(--sec)}
.ch-kpi-sep{width:1px;background:var(--brd);align-self:stretch}

/* ── CAPA 1: SECTION HEADER ──────────────────────────────── */
.l1-section-hdr{display:flex;align-items:baseline;gap:12px;margin-bottom:16px}
.l1-sh-title{font-size:16px;font-weight:800;color:var(--pri)}
.l1-sh-sub{font-size:12px;color:var(--ter)}

/* ── INSTALLATION GRID & CARDS ───────────────────────────── */
.inst-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}

.ic{background:var(--surf);border-radius:18px;border:1px solid var(--brd);box-shadow:var(--shd);overflow:hidden;cursor:pointer;transition:all .2s;display:flex;flex-direction:column}
.ic:not(.ic-ph):hover{transform:translateY(-3px);box-shadow:0 4px 6px rgba(13,27,46,.07),0 16px 48px rgba(13,27,46,.12);border-color:rgba(0,235,200,.4)}
.ic:hover .ic-go{color:var(--teal)}

/* Card header */
.ic-head{padding:16px 20px 12px;border-bottom:1px solid var(--brd);display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.ic-head-l{flex:1;min-width:0}
.ic-srow{display:flex;align-items:center;gap:8px;margin-bottom:5px}
.ic-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
.ic-dot.online{background:var(--pos);box-shadow:0 0 5px rgba(16,185,129,.8)}
.ic-dot.offline{background:var(--neg)}
.ic-dot.nodata{background:var(--ter)}   /* B-06 R1: respondió sin datos o no disponible */
.ic-name{font-size:15px;font-weight:800;color:var(--pri)}
.ic-tbadge{display:inline-block;padding:3px 9px;border-radius:20px;font-size:9px;font-weight:700}
.ic-tbadge.em{background:rgba(0,0,140,.08);color:var(--navy)}
.ic-tbadge.pisc{background:rgba(99,102,241,.08);color:var(--ind)}

/* Health badge on card */
.ic-hbadge{flex-shrink:0}

/* MAIN KPI */
.ic-kpi-main{padding:18px 20px 10px;flex:1}
.ic-kpi-big{font-size:52px;font-weight:800;color:var(--pri);letter-spacing:-.04em;line-height:1;font-variant-numeric:tabular-nums}
.ic-kpi-unit{font-size:13px;font-weight:600;color:var(--sec);margin-top:4px}

/* Secondary KPIs */
.ic-kpi-sec{padding:0 20px 16px;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.ics-item{background:#F4F8FC;border-radius:9px;padding:10px 12px}
/* Label secundario: texto descriptivo puro, uppercase ok */
.ics-lbl{font-size:10px;color:var(--ter);margin-bottom:3px}
.ics-val{font-size:14px;font-weight:700;color:var(--pri);font-variant-numeric:tabular-nums}

/* Sparkline */
.ic-spark{height:52px;background:#F8FAFC;border-top:1px solid #EEF2F7;border-bottom:1px solid #EEF2F7}

/* Card footer */
.ic-footer{padding:10px 20px;display:flex;justify-content:space-between;align-items:center}
.ic-last{font-size:10px;color:var(--ter)}
.ic-go{font-size:11px;font-weight:700;color:var(--navy);transition:color .15s}

/* Placeholder card */
.ic-ph{cursor:default;background:rgba(0,0,140,.02);border:2px dashed rgba(0,0,140,.15);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:36px 24px;gap:10px;min-height:280px}
.ic-ph:hover{transform:none;border-color:rgba(0,0,140,.15)}
.iph-ico{width:46px;height:46px;border-radius:50%;background:rgba(0,0,140,.07);border:2px dashed rgba(0,0,140,.18);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:200;color:var(--navy)}
.iph-title{font-size:14px;font-weight:700;color:var(--navy)}
.iph-sub{font-size:10px;color:var(--ter);text-align:center;line-height:1.5}
.iph-badge{background:rgba(0,235,200,.08);border:1px solid rgba(0,235,200,.2);border-radius:6px;padding:4px 10px;font-size:9px;font-weight:800;color:var(--navy);letter-spacing:.08em}

/* ── VERSION BADGE ───────────────────────────────────────── */
.pf-vbadge{position:fixed;bottom:14px;right:14px;background:rgba(0,0,140,.85);border-radius:10px;padding:6px 12px;font-size:9px;font-weight:700;color:rgba(255,255,255,.45);letter-spacing:.1em;text-transform:uppercase;pointer-events:none}

/* ── LEGIBILIDAD: Header ── */
#pf-online-txt { font-size: 12px; color: rgba(255,255,255,.8); }
.pf-uname      { font-size: 12px; }
.pf-urole      { font-size: 10px; color: rgba(255,255,255,.55); }

/* ── LEGIBILIDAD: Capa 0 ── */
.l0-sub        { font-size: 13px; color: var(--sec); }
.l0-total-badge{ font-size: 12px; color: var(--sec); }
.l0-total-badge span { font-size: 15px; }

/* ── LEGIBILIDAD: Filas de cliente ── */
.cr-loc        { font-size: 11px; color: var(--sec); }
.cr-upd        { font-size: 11px; color: var(--sec); }
.cr-go         { font-size: 12px; }

/* ── LEGIBILIDAD: Cards de instalación ── */
.ics-lbl       { font-size: 11px; color: var(--sec); }
.chk-lbl       { font-size: 10px; color: var(--sec); }
.ic-last       { font-size: 11px; color: var(--sec); }

/* ── LEGIBILIDAD: Wizard boxes — hover igual que cards reales ── */
.cl-row.placeholder { cursor: pointer; }
.cl-row.placeholder:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0,0,0,.08);
  border-color: rgba(0,235,200,.35);
}
.ic-ph { cursor: pointer; }
.ic-ph:hover {
  transform: translateY(-3px);
  box-shadow: 0 4px 6px rgba(13,27,46,.07), 0 16px 48px rgba(13,27,46,.12);
  border-color: rgba(0,235,200,.4);
}

/* ── LEGIBILIDAD: Stats en filas de cliente (capa 0) ── */
.cr-stat-v { font-size: 17px; }
.cr-stat-l { font-size: 10px; color: var(--sec); }

/* ── LEGIBILIDAD: Wizard nuevo cliente (capa 0) ── */
.cl-ph-name { font-size: 15px; }
.cl-ph-sub  { font-size: 12px; color: var(--sec); }

/* ── LEGIBILIDAD: Meta del cliente (capa 1) ── */
.ch-meta > span { font-size: 12px; color: var(--sec); }
.ch-email       { font-size: 12px; color: var(--sec); }

/* ── LEGIBILIDAD: Subtítulo sección instalaciones (capa 1) ── */
.l1-sh-sub { font-size: 13px; color: var(--sec); }

/* ── LEGIBILIDAD: Wizard nueva instalación (capa 1) ── */
.iph-title { font-size: 15px; }
.iph-sub   { font-size: 11px; color: var(--sec); }

/* ── RESPONSIVE ─────────────────────────────────────────── */
@media(max-width:1100px){
  .cl-row-inner{grid-template-columns:auto 1fr auto auto}
  .cr-trend-wrap{display:none}
}
@media(max-width:900px){
  #pf-body{padding:14px 16px 60px}
  #pf-kpis{grid-template-columns:repeat(2,1fr)}
  .inst-grid{grid-template-columns:repeat(2,1fr)}
  .cl-row-inner{grid-template-columns:auto 1fr auto}
  .cr-stats{gap:16px}
  .cr-meta{display:none}
}
@media(max-width:600px){
  .inst-grid{grid-template-columns:1fr}
  #pf-kpis{grid-template-columns:repeat(2,1fr)}
  .ch-kpis{display:none}
}
/* B-06: lista vacía (fail-closed) */
.pf-vacio{padding:28px 24px;border:1px dashed var(--brd);border-radius:12px;background:var(--surf);color:var(--sec);font-size:13px;font-weight:600;text-align:center}

controllerScript.body:
/**
 * SUNKUU 360 — Portal de Flota v2 · JavaScript
 * ThingsBoard PE 4.3.0PE
 *
 * Mejoras v2:
 *  1. Capa 0 = CRM list (filas densas) vs Capa 1 = account drill-down
 *  2. KPI bar diferenciada por capa (gestión vs operacional)
 *  3. Health badge por instalación (NORMAL / ATENCIÓN / ALERTA)
 *  4. Alert ribbon si hay alarmas activas
 *  5. Client hero con identidad prominente en Capa 1
 *  6. Cards rediseñados: KPI principal enorme + sparkline full-width
 *
 * B-06: customers e instalaciones desde el registro (sunkuu-registro.js); Capa 0 sin instalaciones de prueba;
 *       costo del mes (I-03) y estado por instalación y sesión (I-04) con las funciones de FIX-01.
 * B-06 R1: sin datos → "—" y punto gris (nunca NaN ni "hace 0 seg"); "Cargando…" → "Sin datos" / "No disponible";
 *       solo cuentan las alarmas activas del propio dispositivo;
 *       un dispositivo con 404 o 403 no se vuelve a consultar hasta la próxima carga;
 *       sin ningún dato válido → badge "SIN DATOS" / "NO DISPONIBLE" (ATENCIÓN: problema de instalación).
 */
self.onInit = function () {
  var ctx = self.ctx;
  ctx.$container.css({'overflow':'hidden','height':'100%'});
  /* ── LAYOUT: usa ctx.height de TB (garantizado en px) ──── */
  function applyLayout() {
    var hdr  = el('pf-hdr');
    var body = el('pf-body');
    if (!hdr || !body) return;
    /* window.innerHeight = alto real del viewport.
       Si el widget es más alto que la pantalla, el body se limita al viewport
       → el scroll interno del body actúa → el header nunca desaparece.
       Si el widget es más pequeño que la pantalla, se usa ctx.height. */
    var viewH   = window.innerHeight;
    var widgetH = ctx.height || ctx.$container[0].offsetHeight || viewH;
    var bodyH   = Math.min(widgetH, viewH) - hdr.offsetHeight;
    body.style.height = Math.max(200, bodyH) + 'px';
  }
  setTimeout(applyLayout, 50); /* pequeño delay para que TB termine de renderizar */

  /* ── CONFIGURACIÓN CENTRAL (B-06: desde el registro) ───────── */
  /* Instalaciones: sunkuu-registro.js (B-02), declarado en el editor JavaScript con alias registroMod.
   * ThingsBoard filtra por permisos: un usuario de customer solo recibe sus instalaciones.
   * Sin registro o con error → lista vacía y mensaje (fail-closed).
   * Customers (admin): propietarios distintos del registro; UUID, ubicación y email desde entitiesQuery CUSTOMER.
   * Capa 0 (filas, KPI, cinta, estado de la flota): solo es_prueba = false. Capa 1: todas las del customer. */
  var REG = (typeof registroMod !== 'undefined' && registroMod && registroMod.loadInstallations) ? registroMod : window.SunkuuRegistro;
  var ADMIN_DASHBOARD = '4e39b9b0-d090-11f1-aa6f-7f75b1e7584b';   /* Administración — Sunkuu 360 (B-03), solo TENANT_ADMIN */
  /* Estado (min) si el dispositivo no tiene estado_alerta_h / estado_desconexion_h: los valores de producción por tipo */
  var EST_DEF = { '3em': { alerta: 120, desc: 360 }, piscina: { alerta: 720, desc: 1800 } };
  /* Color del customer derivado de su UUID (P-7): FNV-1a del UUID → [degradado, sólido]. El orden deja a Gocta (7) y
     Tucán (6) con sus colores de producción; los 4 customers actuales no se repiten (comprobado en las pruebas). */
  var PALETA = [
    ['linear-gradient(135deg,#0E7490,#0891B2)', '#0E7490'],
    ['linear-gradient(135deg,#7C3AED,#6D28D9)', '#7C3AED'],
    ['linear-gradient(135deg,#B45309,#D97706)', '#B45309'],
    ['linear-gradient(135deg,#047857,#059669)', '#047857'],
    ['linear-gradient(135deg,#BE185D,#DB2777)', '#BE185D'],
    ['linear-gradient(135deg,#1D4ED8,#2563EB)', '#1D4ED8'],
    ['linear-gradient(135deg,#6366F1,#4F46E5)', '#6366F1'],
    ['linear-gradient(135deg,#00008C,#0a0abb)', '#00008C']
  ];

  var CUSTOMERS = [];       /* { id, name, uuid, letter, color, solid, location, email } */
  var INSTALLATIONS = [];   /* { id, name, customer, type, deviceId, dashboardId, esPrueba } */

  /* ── ESTADO ─────────────────────────────────────────────── */
  var currentLayer   = 0;
  var selectedClient = null;
  var isCustomerUser = false;
  var curUser        = ctx.currentUser || {};
  var loaded         = false;

  /* liveData[instId] = { kw, kwh, fp, temp, calOn, lastTs, sparkData, alarmCount, health, tarifa, estAlertaH, estDescH, projKwh } */
  var D = {};

  /* ── HELPERS ────────────────────────────────────────────── */
  var LIMA_OFFSET=-5*3600000, DAY_MS=86400000;
  function nowMs()       { return Date.now(); }
  function todayStart()  { return limaMidnight(0); }   /* FIX-01: medianoche de Lima, no la del navegador */
  function daysAgo(n)    { return nowMs()-n*86400000; }
  function pad(n)        { return n<10?'0'+n:''+n; }
  function fmtKw(w)      { return (w/1000).toFixed(1); }
  function fmtT(v)       { return parseFloat(v).toFixed(1); }
  function timeSince(ts) {
    if(!ts) return 'sin datos';
    var s=Math.floor((nowMs()-ts)/1000);
    if(s<60)   return 'hace '+s+' seg';
    if(s<3600) return 'hace '+Math.floor(s/60)+' min';
    return 'hace '+Math.floor(s/3600)+'h';
  }
  /* R1 · último valor válido: para una clave sin datos ThingsBoard responde [{ts: <ahora>, value: null}] */
  function ultimo(d,k)  {
    var a=d&&d[k], v=a&&a.length?a[0].value:null;
    if(v===null||v===undefined||v==='') return null;
    var n=parseFloat(v); return isFinite(n)?{v:n,ts:+a[0].ts}:null;
  }
  /* R1 · lectura del último valor: undefined = cargando · 'ok' · 'sin' (sin datos) · 'nd' (no disponible).
     Un 404 o un 403 marca el dispositivo: no se vuelve a consultar hasta la próxima carga del widget. */
  function noConsultar(e) { return e===404||e===403; }
  function falloLectura(inst,e) {
    var d=D[inst.id]; if(noConsultar(e)) d.noConsultar=true;
    if(!d.lastTs) d.lectura='nd';
    updateInstCard(inst); updateHealth(inst); updateAggregates();
  }
  function consultable(inst) { return !D[inst.id].noConsultar; }
  function claseDot(inst) { var d=D[inst.id]; return 'ic-dot '+(reciente(inst)?'online':(d.lastTs||!d.lectura?'offline':'nodata')); }
  function el(id)       { return document.getElementById(id); }
  function set(id,v)    { var e=el(id); if(e) e.textContent=v; }
  function htm(id,v)    { var e=el(id); if(e) e.innerHTML=v; }
  function show(id)     { var e=el(id); if(e) e.style.display=''; }
  function hide(id)     { var e=el(id); if(e) e.style.display='none'; }
  function nInst(n, adj) { return n+(n===1?' instalación'+(adj?' '+adj:''):' instalaciones'+(adj?' '+adj+'s':'')); }
  function esc(s)       { return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
  function tsUrl(dev,keys,s,e,iv,ag,lim){
    var u='/api/plugins/telemetry/DEVICE/'+dev+'/values/timeseries?keys='+keys;
    if(s!==undefined) u+='&startTs='+s+'&endTs='+e;
    if(iv) u+='&interval='+iv+'&agg='+(ag||'AVG');
    if(lim) u+='&limit='+lim;
    return u;
  }
  function limaMidnight(offsetDays){
    return Math.floor((nowMs()+LIMA_OFFSET)/DAY_MS)*DAY_MS-LIMA_OFFSET+(offsetDays||0)*DAY_MS;
  }
  /* FIX-01:BEGIN fx — copia literal de las funciones del Template 3EM (373ddd50) que usa Flota (B-06).
     Solo cambia la etiqueta del log de api(): [3EM] → [Fleet]. Comprobado por build_b06.py. */
  var FX_H=3600000, FX_D=86400000, FX_LOOK=7*86400000, FX_MH=2*3600000;   /* FX_MH: tramo del mes (2 h): acota lo que pierde un reset del contador */
  var SESS={lost:false,pingTs:0};
  var SESSION_PING=true;   /* false = solo reintento, sin la llamada de renovación vía ctx.http */
  function fxUrl(dev,key,s,e,iv,ag,lim){
    var u='/api/plugins/telemetry/DEVICE/'+dev+'/values/timeseries?keys='+key+'&startTs='+s+'&endTs='+e;
    u+=iv?'&interval='+iv+'&agg='+ag:'&agg=NONE&orderBy=DESC';
    return u+'&limit='+lim;
  }
  function fxCounterAt(dev,key,ts,cb){
    api(fxUrl(dev,key,ts-FX_LOOK,ts+1,0,'NONE',1),function(d){
      var a=d&&d[key]; cb(a&&a.length?parseFloat(a[0].value):null);
    },function(){ cb(undefined); });
  }
  function fxBuckets(dev,key,t0,t1,iv,cb){
    var n=Math.max(1,Math.ceil((t1-t0)/iv));
    api(fxUrl(dev,key,t0,t1,iv,'MAX',n+2),function(d){
      var a=(d&&d[key])||[], v=[], i;
      for(i=0;i<n;i++) v.push(undefined);
      a.forEach(function(p){
        var k=Math.floor((+p.ts-t0)/iv), x=parseFloat(p.value);
        if(k<0) k=0; if(k>=n) k=n-1;
        if(!isNaN(x)&&(v[k]===undefined||x>v[k])) v[k]=x;
      });
      cb(v);
    },function(){ cb(null); });
  }
  function fxSteps(base,vals){
    var prev=base, out=[], i, v, d;
    for(i=0;i<vals.length;i++){
      v=vals[i];
      if(v===undefined||v===null||isNaN(v)){ out.push(prev===null?null:0); continue; }
      if(prev===null){ out.push(null); prev=v; continue; }
      d=v-prev; out.push(d>0?d/1000:0); prev=v;
    }
    return out;
  }
  function fxSum(steps,from,to){
    var s=0,n=0,i;
    for(i=from;i<to&&i<steps.length;i++){ if(steps[i]!==null){ s+=steps[i]; n++; } }
    return {sum:s,n:n};
  }
  function fxEnergy(dev,key,t0,t1,iv,cb){
    var base,vals,got=0;
    function done(){
      if(++got<2) return;
      if(base===undefined||vals===null){ cb(null); return; }
      var st=fxSteps(base,vals), r=fxSum(st,0,st.length);
      cb({steps:st,total:r.n>0?r.sum:null,hasBase:base!==null});
    }
    fxCounterAt(dev,key,t0,function(b){ base=b; done(); });
    fxBuckets(dev,key,t0,t1,iv,function(v){ vals=v; done(); });
  }
  function fxMonth(){
    var t0=limaMidnight(0), d=new Date(t0+LIMA_OFFSET), y=d.getUTCFullYear(), m=d.getUTCMonth();
    var start=Date.UTC(y,m,1)-LIMA_OFFSET, end=Date.UTC(y,m+1,1)-LIMA_OFFSET;
    return {start:start,end:end,days:Math.round((end-start)/FX_D),closed:Math.round((t0-start)/FX_D)};
  }
  function fxProject(mtd,closedSum,closedDays,now,monthEnd){
    if(mtd===null||!(closedDays>=1)) return null;
    return mtd+closedSum/closedDays*((monthEnd-now)/FX_D);
  }
  function fxMonthEnergy(dev,key,now,cb){
    var M=fxMonth(), per=FX_D/FX_MH;
    fxEnergy(dev,key,M.start,now,FX_MH,function(r){
      if(!r){ cb(null); return; }
      var c=fxSum(r.steps,0,M.closed*per);
      cb({mtd:r.total,projKwh:fxProject(r.total,c.sum,c.n/per,now,M.end)});
    });
  }
  function sessionPing(){
    if(!SESSION_PING) return;
    var t=Date.now(); if(t-SESS.pingTs<5000) return; SESS.pingTs=t;
    try{ ctx.http.get('/api/auth/user').subscribe(function(){},function(){}); }catch(e){}
  }
  function sessionLost(){ if(SESS.lost) return; SESS.lost=true; try{ updateLastSeen(); }catch(e){} }
  function sessionBack(){ if(!SESS.lost) return; SESS.lost=false; try{ updateLastSeen(); }catch(e){} }
  function api(url, ok, fail) {
    function go(retried){
      var token = localStorage.jwt_token || '';
      fetch(url, {headers:{'X-Authorization':'Bearer '+token}})
        .then(function(r){ if(r.status===401) return Promise.reject({auth:true}); return r.ok ? r.json() : Promise.reject(r.status); })
        .then(function(d){ sessionBack(); return ok(d); })
        .catch(function(e){
          if(e && e.auth){
            if(!retried){ sessionPing(); setTimeout(function(){ go(true); }, 2000); return; }
            sessionLost(); e=401;
          }
          if(fail) fail(e); else console.warn('[Fleet]',e);
        });
    }
    go(false);
  }
  /* FIX-01:END fx */

  /* ── REGISTRO → CUSTOMERS / INSTALLATIONS ───────────────── */
  function flota(inst)  { return REG.CATALOGO[inst.type].flota; }   /* claves de telemetría del catálogo */
  function colorDe(uuid, name) {
    var s = uuid || name || '', h = 2166136261;
    for (var i=0;i<s.length;i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
    return PALETA[h % PALETA.length];
  }
  function ubicacion(c) {
    var parts=[c.city||'', (c.state||c.country||'')].filter(function(s){return s&&s.trim();});
    return parts.length ? '📍 '+parts.join(', ') : '';
  }
  function nuevoCustomer(name, info) {
    var col = colorDe(info.uuid, name);
    var c = { id:'c'+CUSTOMERS.length, name:name, uuid:info.uuid||null, letter:(name.trim().charAt(0)||'?').toUpperCase(),
              color:col[0], solid:col[1], location:ubicacion(info), email:info.email||'' };
    CUSTOMERS.push(c);
    return c;
  }
  function construir(lista, clientes) {
    var porNombre = {};
    lista.forEach(function (i) {
      var dev = REG.dispositivoFlota(i);
      if (!dev) { console.warn('[Fleet] '+i.etiqueta+': el tipo '+i.tipo+' no tiene dispositivo para Flota, se omite'); return; }
      var c = porNombre[i.owner] || (porNombre[i.owner] = nuevoCustomer(i.owner, clientes[i.owner] || {}));
      INSTALLATIONS.push({ id:i.id, name:i.etiqueta, customer:c.id, type:i.tipo, deviceId:dev, dashboardId:i.dashboardId, esPrueba:i.esPrueba });
    });
    CUSTOMERS.sort(function(a,b){ return a.name.localeCompare(b.name,'es'); });
    INSTALLATIONS.forEach(function (i) {
      D[i.id] = { kw:null, kwh:null, kwhYday:undefined, fp:null, temp:null, calOn:null, lastTs:null, sparkData:[], alarmCount:0, health:{level:'NORMAL',reason:'Cargando'},
                  attrsOk:false, tarifa:null, estAlertaH:null, estDescH:null, projKwh:null, projLoaded:false };
    });
  }
  function leerClientes(resp) {
    var out = {};
    ((resp && resp.data) || []).forEach(function (row) {
      var f = (row.latest && row.latest.ENTITY_FIELD) || {};
      function v(k){ return f[k] && f[k].value ? f[k].value : ''; }
      if (v('title')) out[v('title')] = { uuid: row.entityId.id, city: v('city'), state: v('state'), country: v('country'), email: v('email') };
    });
    return out;
  }
  var CUST_QUERY = {
    entityFilter: { type:'entityType', entityType:'CUSTOMER' },
    entityFields: ['title','city','state','country','email'].map(function(k){ return { type:'ENTITY_FIELD', key:k }; }),
    pageLink: { page:0, pageSize:200, sortOrder:{ key:{ type:'ENTITY_FIELD', key:'title' }, direction:'ASC' } }
  };

  /* Alcance: Capa 0 = instalaciones fuera de prueba; Capa 1 = todas las del customer (usuario del customer: todas las suyas) */
  function capa0Insts()     { return INSTALLATIONS.filter(function(i){return !i.esPrueba;}); }
  function capa0Customers() { var ins=capa0Insts(); return CUSTOMERS.filter(function(c){return ins.some(function(i){return i.customer===c.id;});}); }
  function instsDe(cust)    { return (!cust||cust.todas) ? INSTALLATIONS : INSTALLATIONS.filter(function(i){return i.customer===cust.id;}); }
  function scopeInsts()     { return currentLayer===1 ? instsDe(selectedClient) : capa0Insts(); }

  /* Estado por instalación (I-04): umbrales del dispositivo; si faltan, los de producción por tipo */
  function umbrales(inst) {
    var d = D[inst.id], def = EST_DEF[inst.type] || EST_DEF['3em'];
    var a = d.estAlertaH>0 ? d.estAlertaH*60 : def.alerta, x = d.estDescH>0 ? d.estDescH*60 : def.desc;
    if (!(x>a)) { a=def.alerta; x=def.desc; }
    return { alerta:a, desc:x };
  }
  function reciente(inst) { var d=D[inst.id]; return !!d.lastTs && (nowMs()-d.lastTs)/60000 <= umbrales(inst).alerta; }

  /* ── HEALTH COMPUTATION ─────────────────────────────────── */
  function computeHealth(inst) {
    var d = D[inst.id];
    /* Alarms: highest priority */
    if (d.alarmCount > 0) return { level:'alerta', text:'⚠ '+d.alarmCount+' alarma'+(d.alarmCount>1?'s':''), reason:'Alarmas activas' };
    /* R1 · sin ningún dato válido: problema de instalación (cuenta en "Requieren acción" y en la cinta) */
    if (!d.lastTs && d.lectura==='sin') return { level:'atencion', text:'⚠ SIN DATOS',     reason:'Nunca envió datos' };
    if (!d.lastTs && d.lectura==='nd')  return { level:'atencion', text:'⚠ NO DISPONIBLE', reason:'Dispositivo no disponible' };
    /* Last seen: umbrales del dispositivo (estado_alerta_h / estado_desconexion_h) o los de su tipo */
    if (d.lastTs) {
      var age = (nowMs()-d.lastTs)/60000, lim = umbrales(inst);
      if (age > lim.desc)   return { level:'alerta',  text:'⚠ SIN SEÑAL', reason:'Sin datos hace '+Math.round(age)+' min' };
      if (age > lim.alerta) return { level:'atencion', text:'⚠ ATENCIÓN',  reason:'Sin datos hace '+Math.round(age)+' min' };
    }
    /* FP check for 3EM */
    if (inst.type==='3em' && d.fp!==null) {
      if (d.fp < 0.85) return { level:'alerta',   text:'⚠ FP BAJO',   reason:'FP: '+d.fp.toFixed(2)+' — revisar cargas' };
      if (d.fp < 0.95) return { level:'atencion', text:'⚠ ATENCIÓN',  reason:'FP limitado: '+d.fp.toFixed(2) };
    }
    /* Temp check for piscina */
    if (inst.type==='piscina' && d.temp!==null) {
      if (d.temp > 35) return { level:'alerta',  text:'⚠ TEMP. ALTA', reason:'Piscina: '+fmtT(d.temp)+'°C' };
      if (d.temp < 30) return { level:'alerta',  text:'⚠ TEMP. BAJA', reason:'Piscina: '+fmtT(d.temp)+'°C' };
    }
    return { level:'normal', text:'✓ NORMAL', reason:'Operando con normalidad' };
  }

  function updateHealth(inst) {
    D[inst.id].health = computeHealth(inst);
    updateHealthDOM(inst);
    updateAlertRibbon();
    updateClientRowHealth();
  }

  function updateHealthDOM(inst) {
    var h = D[inst.id].health;
    /* In Layer 1 card */
    var hb = el('ic-hb-'+inst.id);
    if (hb) { hb.className='hb '+h.level; hb.textContent=h.text; }
    var dot = el('ic-dot-'+inst.id);
    if (dot) dot.className=claseDot(inst);   /* R1: gris si respondió sin datos */
  }

  function customerHealth(custId) {
    var insts = capa0Insts().filter(function(i){return i.customer===custId;});
    var worst = 'normal';
    var worstReason = 'Operando con normalidad';
    insts.forEach(function(i){
      var h = D[i.id].health;
      if (h.level==='alerta')  { worst='alerta';   worstReason=i.name+': '+h.reason; }
      if (h.level==='atencion' && worst!=='alerta') { worst='atencion'; worstReason=i.name+': '+h.reason; }
    });
    return { level:worst, text: worst==='alerta'?'⚠ ALERTA': worst==='atencion'?'⚠ ATENCIÓN':'✓ NORMAL', reason:worstReason };
  }

  function updateClientRowHealth() {
    capa0Customers().forEach(function(c){
      var h = customerHealth(c.id);
      var badge = el('cr-hb-'+c.id);
      var bar   = el('cr-bar-'+c.id);
      if (badge) { badge.className='hb '+h.level; badge.textContent=h.text; }
      if (bar)   { bar.className='cl-row-bar '+h.level; }
      var reason = el('cr-reason-'+c.id);
      if (reason) reason.textContent = h.level !== 'normal' ? h.reason : '';
    });
  }

  function updateAlertRibbon() {
    var ribbon = el('pf-alert');
    if (!ribbon) return;
    var fa=getFleetAttention();
    if(fa.count===0){
      ribbon.style.display='none';
      return;
    }
    ribbon.style.display='flex';
    var isRiesgo=fa.level==='alerta';
    var rc=isRiesgo?'239,68,68':'245,158,11';
    var tc=isRiesgo?'#991B1B':'#92400E';
    ribbon.style.background='rgba('+rc+',.08)';
    ribbon.style.border='1px solid rgba('+rc+',.22)';
    var dot=ribbon.querySelector('.pal-dot');
    if(dot){dot.style.background=isRiesgo?'#EF4444':'#F59E0B';dot.style.boxShadow='0 0 6px rgba('+rc+',.7)';}
    var txt=ribbon.querySelector('#pf-alert-txt');
    if(txt) txt.style.color=tc;
    var btn=ribbon.querySelector('.pal-btn');
    if(btn){btn.style.color=isRiesgo?'#EF4444':'#F59E0B';btn.style.background='rgba('+rc+',.12)';btn.style.borderColor='rgba('+rc+',.28)';}
    var names=[];
    scopeInsts().forEach(function(i){
      var h=D[i.id].health;
      if(h.level==='alerta'||h.level==='atencion') names.push(i.name+': '+h.reason);
    });
    var msg = fa.count===1
      ? '⚠ 1 instalación requiere acción: '+names[0]
      : '⚠ '+fa.count+' instalaciones requieren acción: '+names.join(' · ');
    set('pf-alert-txt', msg);
  }

  /* ── SPARKLINE ──────────────────────────────────────────── */
  function buildSpark(data,color){
    if(!data||data.length<2) return '';
    var W=400,H=52;
    var mn=Math.min.apply(null,data),mx=Math.max.apply(null,data),rng=mx-mn||1;
    var pts=data.map(function(v,i){return[+(i/(data.length-1)*W).toFixed(1),+(H-2-((v-mn)/rng)*(H-4)).toFixed(1)];});
    var ln=pts.map(function(p,i){return(i===0?'M':'L')+p[0]+','+p[1];}).join(' ');
    var uid='g'+Math.random().toString(36).slice(2,7);
    return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" height="'+H+'" preserveAspectRatio="none" style="display:block">'+
      '<defs><linearGradient id="'+uid+'" x1="0" y1="0" x2="0" y2="1">'+
      '<stop offset="0%" stop-color="'+color+'" stop-opacity=".3"/>'+
      '<stop offset="100%" stop-color="'+color+'" stop-opacity="0"/>'+
      '</linearGradient></defs>'+
      '<path d="'+ln+' L'+W+','+H+' L0,'+H+' Z" fill="url(#'+uid+')"/>'+
      '<path d="'+ln+'" fill="none" stroke="'+color+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  }

  /* ── DETECT USER ────────────────────────────────────────── */
  isCustomerUser = curUser.authority==='CUSTOMER_USER';
  (function(){
    var uname = ((curUser.firstName||'')+' '+(curUser.lastName||'')).trim() || curUser.email || curUser.sub || 'Usuario';
    set('pf-uname', uname);
    set('pf-uav', uname.charAt(0).toUpperCase());
    if (isCustomerUser) set('pf-urole', 'Customer');
  })();

  /* Encabezado: instalaciones con datos recientes (o sesión expirada, I-04) */
  function updateLastSeen() {
    var dot = document.querySelector('#pf-hdr .pf-odot');
    if (SESS.lost) { set('pf-online-txt','Sesión expirada — recargar'); if(dot){dot.style.background='#EF4444';dot.style.boxShadow='none';} return; }
    if (dot) { dot.style.background=''; dot.style.boxShadow=''; }
    if (!loaded) return;
    if (isCustomerUser) { set('pf-online-txt', nInst(INSTALLATIONS.length,'activa')); return; }
    var ins = capa0Insts(), rec = ins.filter(reciente).length;
    set('pf-online-txt', rec+' de '+nInst(ins.length,'activa'));
  }

  function mostrarVacio(msg) {
    var box = isCustomerUser ? el('inst-grid') : el('client-list');
    if (box) box.innerHTML = '<div class="pf-vacio">'+esc(msg)+'</div>';
  }

  /* Usuario del customer: ubicación y email de su customer; si falla, se omiten */
  function loadOwnCustomer() {
    if (!curUser.customerId) return;
    api('/api/customer/'+curUser.customerId, function(data) {
