  function renderFleetState() {
      var card = document.getElementById('fleet-state-card');
      if (!card) return;
      var ins = capa0Insts();
      var total = ins.length, estables = 0, atencion = 0, riesgo = 0, sinSenal = 0;
      var riesgoInst = [], atencionInst = [];
      ins.forEach(function(i) {
        var h = D[i.id].health;
        if      (h.level === 'alerta')   { riesgo++;  riesgoInst.push(i.name);  }
        else if (h.level === 'atencion') { atencion++; atencionInst.push(i.name); }
        else if (h.level === 'normal') {
          if (D[i.id].lastTs && !reciente(i)) sinSenal++;
          else estables++;
        } else sinSenal++;
      });
      var level, icon, borderColor, bgColor, badgeText, badgeBg, badgeColor;
      if (riesgo > 0) {
        level='riesgo';icon='error';borderColor='#EF4444';bgColor='rgba(239,68,68,.05)';badgeBg='rgba(239,68,68,.1)';badgeColor='#DC2626';badgeText='Riesgo detectado';
      } else if (atencion > 0) {
        level='atencion';icon='warning_amber';borderColor='#F59E0B';bgColor='rgba(245,158,11,.05)';badgeBg='rgba(245,158,11,.1)';badgeColor='#D97706';badgeText='Atención requerida';
      } else if (sinSenal > 0) {
        level='sin-senal';icon='signal_wifi_off';borderColor='#96AABF';bgColor='rgba(150,170,191,.05)';badgeBg='rgba(150,170,191,.1)';badgeColor='#5A6E8A';badgeText='Sin señal en '+sinSenal+(sinSenal===1?' instalación':' instalaciones');
      } else {
        level='estable';icon='check_circle';borderColor='#10B981';bgColor='rgba(16,185,129,.05)';badgeBg='#ECFDF5';badgeColor='#10B981';badgeText='Flota operativa';
      }
      var lines = [];
      if (level==='estable') {
        lines.push(nInst(total,'monitoreada')+'. Todas operan dentro de los parámetros configurados.');
        lines.push('No se detectan interrupciones ni anomalías en este período.');
      } else if (level==='atencion') {
        lines.push((atencion===1?'1 instalación requiere':atencion+' instalaciones requieren')+' atención: '+atencionInst.join(', ')+'.');
        if (estables>0) lines.push(estables+(estables===1?' instalación opera':' instalaciones operan')+' con normalidad.');
        lines.push('Se recomienda revisar la evolución durante las próximas horas.');
      } else if (level==='riesgo') {
        lines.push(riesgo+(riesgo===1?' instalación presenta':' instalaciones presentan')+' riesgo operativo: '+riesgoInst.join(', ')+'.');
        if (atencion>0) lines.push(atencion+' adicional'+(atencion>1?'es':'')+' en estado de atención.');
        lines.push('Se requiere verificación inmediata.');
      } else {
        lines.push('Sin datos recientes en '+sinSenal+(sinSenal===1?' instalación.':' instalaciones.'));
        if (estables>0) lines.push(estables+(estables===1?' instalación':' instalaciones')+' operando con normalidad.');
      }
      card.innerHTML=
        '<div style="background:'+bgColor+';border:1px solid '+borderColor+'33;border-left:3px solid '+borderColor+';border-radius:10px;padding:12px 16px">'+
          '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">'+
            '<span style="font-family:\'Material Icons\';font-size:16px;color:'+badgeColor+'">'+icon+'</span>'+
            '<span style="font-size:10px;font-weight:700;color:'+badgeColor+';text-transform:uppercase;letter-spacing:.5px">Estado de la flota hoy</span>'+
            '<span style="margin-left:auto;font-size:10px;padding:2px 8px;background:'+badgeBg+';color:'+badgeColor+';border-radius:12px;font-weight:700">'+badgeText+'</span>'+
          '</div>'+
          lines.map(function(l,i){return '<div style="font-size:12px;color:#0D1B2E;line-height:1.5;'+(i>0?'margin-top:3px;opacity:.75':'font-weight:500')+'">'+esc(l)+'</div>';}).join('')+
        '</div>';
    }

  function getFleetAttention() {
    var count=0, worstLevel='normal', worstCause='';
    scopeInsts().forEach(function(i){
      var h=D[i.id].health;
      if(h.level==='alerta'){
        count++;
        if(worstLevel!=='alerta'){worstLevel='alerta';worstCause=h.reason;}
      } else if(h.level==='atencion'){
        count++;
        if(worstLevel==='normal'){worstLevel='atencion';worstCause=h.reason;}
      }
    });
    return {count:count, level:worstLevel, cause:worstCause};
  }

  /* Costo de energía estimado del mes (I-03): Σ proyección (método B de FIX-01) × tarifa_kwh del dispositivo.
     Solo 3EM fuera de prueba (la piscina no entra, como en producción). Sin tarifa_kwh → fuera del costo, con aviso. */
  function renderCost() {
    var tot=0, n=0, pend=false, sinTarifa=[], sinDatos=[];
    capa0Insts().forEach(function(i){
      if (i.type!=='3em') return;
      var d=D[i.id];
      if (!d.attrsOk || !d.projLoaded) { pend=true; return; }
      if (!(d.tarifa>0))     { sinTarifa.push(i.name); return; }
      if (d.projKwh===null)  { sinDatos.push(i.name); return; }
      tot+=d.projKwh*d.tarifa; n++;
    });
    var s4El=el('pk-s4');
    if (fxMonth().closed<1) { set('pk-v4','—'); set('pk-s4','Disponible desde el 2.º día del mes'); return; }
    if (pend) return;
    var notas=[];
    if (sinTarifa.length) notas.push('sin tarifa_kwh: '+sinTarifa.join(', '));
    if (sinDatos.length)  notas.push('sin datos del mes: '+sinDatos.join(', '));
    if (notas.length) console.warn('[Fleet] costo del mes: '+notas.join(' · '));
    set('pk-v4', n>0 ? 'S/ '+tot.toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}) : '—');
    set('pk-s4', (n>0?'sin cargo fijo ni IGV':'')+(n>0&&notas.length?' · ':'')+(notas.length?'No incluye — '+notas.join(' · '):''));
    if (s4El) s4El.title = notas.join('\n');
  }

  function updateLayer0Aggregates() {
    var totalKW=0, totalKWH=0, ins=capa0Insts();
    ins.forEach(function(i){
      if(D[i.id].kw!==null)  totalKW+=D[i.id].kw;
      if(D[i.id].kwh!==null) totalKWH+=D[i.id].kwh;
    });
    set('pk-v3', totalKW>0 ? totalKW.toFixed(1) : '—');
    renderCost();
    /* Customers activos: con alguna instalación con datos recientes (por debajo de estado_alerta_h) */
    var custs=capa0Customers();
    set('pk-v1', ''+custs.filter(function(c){return ins.some(function(i){return i.customer===c.id&&reciente(i);});}).length);
    /* Per customer */
    custs.forEach(function(c){
      var insts=ins.filter(function(i){return i.customer===c.id;});
      var ckw=0,ckwh=0,lastTs=null;
      insts.forEach(function(i){if(D[i.id].kw!==null)ckw+=D[i.id].kw;if(D[i.id].kwh!==null)ckwh+=D[i.id].kwh;if(D[i.id].lastTs&&(!lastTs||D[i.id].lastTs>lastTs))lastTs=D[i.id].lastTs;});
      set('cr-kw-'+c.id,  ckw>0  ? ckw.toFixed(1)+' kW'   : '—');
      set('cr-kwh-'+c.id, ckwh>0 ? ckwh.toFixed(1)+' kWh' : '—');
      if(lastTs) set('cr-upd-'+c.id, timeSince(lastTs));
    });
    /* Condiciones operativas — fuente única via getFleetAttention() */
    var fa=getFleetAttention();
    set('pk-v2', fa.count>0 ? ''+fa.count : '0');
    var av2=el('pk-v2');
    if(av2) av2.parentElement.className='pk-val'+(fa.level==='alerta'?' alert-val':fa.level==='atencion'?' warn-val':' ok-val');
    var s2El=el('pk-s2');
    if(s2El){
      if(fa.count===0)      s2El.textContent='Todas operando normalmente';
      else if(fa.count===1) s2El.textContent='Principal causa: '+fa.cause;
      else                  s2El.textContent=fa.count+' requieren acción · '+fa.cause;
    }

    renderFleetState();
    updateLastSeen();
  }

