  function showLayer1(cust) {
    currentLayer=1;
    selectedClient=cust;
    el('pf-root').className='l1';
    hide('layer0'); show('layer1');

    /* Breadcrumb (admin only) */
    if (!isCustomerUser && cust) {
      show('pf-bc');
      set('bc-name', cust.name);
      var bcAv=el('bc-av'); if(bcAv){bcAv.textContent=cust.letter;bcAv.style.background=cust.solid;}
      el('btn-bc').onclick=function(){showLayer0();};
    } else {
      hide('pf-bc');
    }

    var insts = instsDe(cust);

    /* Client Hero */
    if (cust) {
      var hero=el('ch-hero');
      if(hero) hero.style.borderLeftColor=cust.solid;
      var chAv=el('ch-avatar'); if(chAv){chAv.textContent=cust.letter;chAv.style.background=cust.color;}
      set('ch-name', cust.name || '—');
      set('ch-loc',  cust.location || '—');
      set('ch-inst', insts.length+(insts.length!==1?' instalaciones activas':' instalación activa'));
      if (cust.email) { set('ch-email',cust.email); show('ch-email-sep'); show('ch-email'); }
      else { hide('ch-email-sep'); hide('ch-email'); }
    }
    set('chk-lbl-kw', isCustomerUser ? 'Potencia actual' : 'Potencia del customer');

    /* Section header */
    set('l1-sh-title', 'Instalaciones'+(cust&&cust.name?' de '+cust.name:''));
    set('l1-sh-sub', insts.length+(insts.length!==1?' instalaciones activas':' instalación activa'));

    /* KPI bar update for this client */
    renderLayer1KPIs(cust, insts);

    /* Render cards */
    renderInstCards(insts);

    /* Load data */
    loadAllData(insts);
    updateAlertRibbon();
  }

  function renderLayer1KPIs(cust, insts) {
    if(isCustomerUser){
      set('pk-lbl1','Tus instalaciones');  set('pk-s1','activas');
      set('pk-lbl2','Alertas activas');    set('pk-s2','en tu cuenta');
      set('pk-lbl3','Potencia actual');    set('pk-s3','kW combinado');
      set('pk-lbl4','Energía hoy');        set('pk-s4','kWh acumulados');
    } else {
      set('pk-lbl1','Instalaciones');      set('pk-s1','en este customer');
      set('pk-lbl2','Estado operativo');   set('pk-s2','instalaciones monitoreadas');
      set('pk-lbl3','Potencia del customer'); set('pk-s3','kW combinado');
      set('pk-lbl4','Energía hoy');        set('pk-s4','kWh acumulados');
    }
    var s4El=el('pk-s4'); if(s4El) s4El.title='';
    /* Accent teal para capa 1 */
    ['pkpi1','pkpi2','pkpi3','pkpi4'].forEach(function(id){
      var e=el(id); if(e) e.classList.add('accent');
    });
    set('pk-v1', ''+insts.length);
    set('pk-v3', '—'); set('pk-v4', '—');
    var activeAlerts=insts.reduce(function(s,i){return s+(D[i.id].alarmCount||0);},0);
    set('pk-v2', ''+activeAlerts);
    var av2=el('pk-v2'); if(av2) av2.parentElement.className='pk-val'+(activeAlerts>0?' alert-val':' ok-val');
  }

  function updateLayer1Aggregates(insts) {
    var totalKW=0,totalKWH=0,lastTs=null;
    insts.forEach(function(i){
      if(D[i.id].kw!==null)  totalKW+=D[i.id].kw;
      if(D[i.id].kwh!==null) totalKWH+=D[i.id].kwh;
      if(D[i.id].lastTs&&(!lastTs||D[i.id].lastTs>lastTs)) lastTs=D[i.id].lastTs;
    });
    set('pk-v3', totalKW>0  ? totalKW.toFixed(1) : '—');
    set('pk-v4', totalKWH>0 ? totalKWH.toFixed(1) : '—');
    /* Hero KPIs */
    set('chk-kw',  totalKW>0  ? totalKW.toFixed(1)  : '—');
    set('chk-kwh', totalKWH>0 ? totalKWH.toFixed(1) : '—');
    if(lastTs) set('chk-upd', timeSince(lastTs));
    /* Estado operativo desde computeHealth(), solo las instalaciones de este customer */
    var scopeCount=insts.length;
    var needAction2=0, worstLevel2='normal';
    insts.forEach(function(i){
      var h=D[i.id].health;
      if(h.level==='alerta'||h.level==='atencion') needAction2++;
      if(h.level==='alerta') worstLevel2='alerta';
      else if(h.level==='atencion'&&worstLevel2==='normal') worstLevel2='atencion';
    });
    var normalCount=scopeCount-needAction2;
    var av2L1=el('pk-v2');
    if(av2L1) av2L1.parentElement.className='pk-val'+(worstLevel2==='alerta'?' alert-val':worstLevel2==='atencion'?' warn-val':' ok-val');
    if(needAction2===0){
      set('pk-v2','0');
      set('pk-s2','Todo en orden · '+scopeCount+' de '+scopeCount+' operando normalmente');
    } else {
      set('pk-v2',''+needAction2);
      set('pk-s2',(needAction2===1?'1 requiere revisión':needAction2+' requieren acción')+' · '+normalCount+' de '+scopeCount+' operando normalmente');
    }
    var achEl=el('chk-alarms');
    if(achEl){
      achEl.textContent=needAction2===0?'Todo en orden':(needAction2===1?'1 requiere revisión':needAction2+' requieren acción');
      achEl.style.color=worstLevel2==='alerta'?'#EF4444':worstLevel2==='atencion'?'#F59E0B':'#10B981';
    }
    updateLastSeen();
  }

  /* ── RENDER INSTALLATION CARDS ──────────────────────────── */
  function renderInstCards(insts) {
    var grid=el('inst-grid'); if(!grid) return;
    grid.innerHTML='';
    insts.forEach(function(inst){
      var isPisc=inst.type==='piscina';
      var card=document.createElement('div');
      card.className='ic';
      card.id='ic-card-'+inst.id;
      card.innerHTML=
        /* Head */
        '<div class="ic-head">'+
          '<div class="ic-head-l">'+
            '<div class="ic-srow"><div class="'+claseDot(inst)+'" id="ic-dot-'+inst.id+'"></div><span class="ic-name">'+esc(inst.name)+'</span></div>'+
            '<span class="ic-tbadge '+(isPisc?'pisc':'em')+'">'+(isPisc?'Piscina · DS18B20':'Pro 3EM · Trifásico')+'</span>'+
          '</div>'+
          '<span class="hb normal" id="ic-hb-'+inst.id+'">✓ NORMAL</span>'+
        '</div>'+
        /* Main KPI */
        '<div class="ic-kpi-main">'+
          '<div class="ic-kpi-big" id="ic-big-'+inst.id+'">—</div>'+
          '<div class="ic-kpi-unit" id="ic-unit-'+inst.id+'">'+(isPisc?'°C temperatura piscina':'kW potencia activa')+'</div>'+
        '</div>'+
        /* Secondary KPIs */
        '<div class="ic-kpi-sec">'+
          '<div class="ics-item"><div class="ics-lbl">'+(isPisc?'Calentador':'Energía hoy')+'</div><div class="ics-val" id="ic-s1-'+inst.id+'">—</div></div>'+
          '<div class="ics-item"><div class="ics-lbl">'+(isPisc?'Temperatura piscina':'Factor Pot. avg')+'</div><div class="ics-val" id="ic-s2-'+inst.id+'">—</div></div>'+
        '</div>'+
        /* Sparkline full-width */
        '<div class="ic-spark" id="ic-sp-'+inst.id+'"></div>'+
        /* Footer */
        '<div class="ic-footer"><span class="ic-last" id="ic-last-'+inst.id+'">Cargando…</span><span class="ic-go">Ver dashboard →</span></div>';

      card.addEventListener('click',function(){window.location.href='/dashboard/'+inst.dashboardId;});
      grid.appendChild(card);
      updateInstCard(inst);
      updateHealthDOM(inst);
    });
  }

  /* ══════════════════════════════════════════════════════════
     DATA LOADING
  ══════════════════════════════════════════════════════════ */
  function loadAllData(insts) {
    insts.filter(consultable).forEach(function(inst){   /* R1: sin los dispositivos con 404/403 */
      loadAttrs(inst);
      if (inst.type==='3em')    { load3EMLatest(inst); load3EMHealth(inst); }
      else                       { loadPiscLatest(inst); }
      loadEnergyToday(inst);
      loadEnergyYesterday(inst);
      loadMonthCost(inst);
      loadAlarms(inst);
      loadSparkline(inst);
    });
  }

  /* Atributos del dispositivo (una vez): tarifa_kwh (I-03) y estado_alerta_h / estado_desconexion_h (I-04) */
  function loadAttrs(inst) {
    var d=D[inst.id]; if(d.attrsOk||d.attrsReq) return; d.attrsReq=true;
    api('/api/plugins/telemetry/DEVICE/'+inst.deviceId+'/values/attributes/SERVER_SCOPE?keys=tarifa_kwh,estado_alerta_h,estado_desconexion_h',
      function(attrs){
        (attrs||[]).forEach(function(a){
          var v=parseFloat(a.value);
          if(a.key==='tarifa_kwh')           d.tarifa=v>0?v:null;
          if(a.key==='estado_alerta_h')      d.estAlertaH=v>0?v:null;
          if(a.key==='estado_desconexion_h') d.estDescH=v>0?v:null;
        });
        d.attrsOk=true; updateHealth(inst); updateAggregates();
      },
      function(e){ d.attrsOk=true; if(noConsultar(e)) d.noConsultar=true; updateAggregates(); });
  }

  function load3EMLatest(inst) {
    var k=flota(inst).kw;
    api(tsUrl(inst.deviceId,k,undefined,undefined,undefined,undefined,1),
      function(d){
        var u=ultimo(d,k);   /* R1: sin valor → null (nunca NaN ni la hora de la respuesta) */
        if(u){ D[inst.id].kw=u.v/1000; D[inst.id].lastTs=u.ts; }
        D[inst.id].lectura=D[inst.id].lastTs?'ok':'sin';
        updateInstCard(inst);
        updateHealth(inst);
        updateAggregates();
      },
      function(e){ falloLectura(inst,e); });
  }

  function load3EMHealth(inst) {
    api(tsUrl(inst.deviceId,'factor_potencia_fase_a,factor_potencia_fase_b,factor_potencia_fase_c',undefined,undefined,undefined,undefined,1),
      function(d){
        var fa=ultimo(d,'factor_potencia_fase_a'), fb=ultimo(d,'factor_potencia_fase_b'), fc=ultimo(d,'factor_potencia_fase_c');   /* R1 */
        if(fa&&fb&&fc) D[inst.id].fp=(fa.v+fb.v+fc.v)/3;
        /* Show FP in secondary KPI */
        if(currentLayer===1) { var s2=el('ic-s2-'+inst.id); if(s2&&D[inst.id].fp!==null) s2.textContent=D[inst.id].fp.toFixed(2); }
        updateHealth(inst);
      });
  }

  function loadPiscLatest(inst) {
    var k=flota(inst).temp;
    api(tsUrl(inst.deviceId,k+',estado_salida',undefined,undefined,undefined,undefined,1),
      function(d){
        var u=ultimo(d,k), s=d.estado_salida&&d.estado_salida.length?d.estado_salida[0].value:null;   /* R1 */
        if(u){D[inst.id].temp=u.v;D[inst.id].lastTs=u.ts;}
        if(s!==null&&s!==undefined&&s!=='')D[inst.id].calOn=(s==='true'||s===true);
        D[inst.id].lectura=D[inst.id].lastTs?'ok':'sin';
        updateInstCard(inst);
        updateAggregates();
        updateHealth(inst);
      },
      function(e){ falloLectura(inst,e); });
  }

  /* FIX-01 · Energía por diferencia de contador (último valor ≤ instante). Día = 00:00–24:00 Lima. */
  function loadEnergyToday(inst) {
    if(inst.type==='piscina') return; /* piscina no tiene energía relevante en este contexto */
    var now=nowMs(), t0=limaMidnight(0);
    fxEnergy(inst.deviceId,flota(inst).contador_wh,t0,now,FX_H,function(r){
      D[inst.id].kwh=r?r.total:null;
      updateInstCard(inst);
      updateAggregates();
      updateTrend();
    });
  }

  /* R1 · alarmas activas del propio dispositivo: status ACTIVE_*, no borrada y originador = el dispositivo
     (sin originador en la respuesta, se cuenta). Lo contado y lo ignorado va a la consola para diagnosticar. */
  function loadAlarms(inst) {
    api('/api/alarm/DEVICE/'+inst.deviceId+'?page=0&pageSize=10&fetchOriginator=false&statusList=ACTIVE_UNACK,ACTIVE_ACK',
      function(d){
        var lista=(d&&Array.isArray(d.data))?d.data:[], activas=0;
        if(!d||!Array.isArray(d.data)) console.warn('[Fleet] alarmas de '+inst.name+': respuesta sin data[], se cuentan 0');
        lista.forEach(function(a){
          var propia=!!a&&(!a.originator||a.originator.id===inst.deviceId);
          var activa=!!a&&typeof a.status==='string'&&a.status.indexOf('ACTIVE_')===0&&a.cleared!==true;
          if(propia&&activa) activas++;
        });
        if(lista.length) console.info('[Fleet] alarmas de '+inst.name+': '+activas+' activas propias, '+(lista.length-activas)+' ignoradas',
          lista.map(function(a){ return a&&{id:a.id&&a.id.id, type:a.type, originator:a.originator&&a.originator.id, status:a.status, cleared:a.cleared, createdTime:a.createdTime}; }));
        D[inst.id].alarmCount=activas;
        updateHealth(inst);
        updateAggregates();
      },
      function(e){ D[inst.id].alarmCount=0; if(noConsultar(e)) D[inst.id].noConsultar=true; updateHealth(inst); updateAggregates(); });
  }

  /* FIX-01 · Ayer en el mismo tramo (00:00 → hora actual), para comparar con hoy */
  function loadEnergyYesterday(inst) {
    if (inst.type !== '3em') return;
    var now=nowMs(), t0=limaMidnight(0);
    fxEnergy(inst.deviceId, flota(inst).contador_wh, t0-FX_D, now-FX_D, FX_H, function(r) {
      D[inst.id].kwhYday = r ? r.total : null;
      updateTrend();
    });
  }

  /* I-03 · Proyección del mes (método B de FIX-01) para el costo de la Capa 0 */
  function loadMonthCost(inst) {
    if (inst.type !== '3em' || inst.esPrueba || currentLayer!==0) return;
    fxMonthEnergy(inst.deviceId, flota(inst).contador_wh, nowMs(), function(m) {
      D[inst.id].projKwh = m ? m.projKwh : null; D[inst.id].projLoaded = true;
      updateAggregates();
    });
  }

  function updateTrend() {
    capa0Customers().forEach(function(c) {
      var insts = capa0Insts().filter(function(i) { return i.customer === c.id && i.type === '3em'; });
      var todayTotal = 0, ydayTotal = 0, allReady = true;
      insts.forEach(function(i) {
        if (D[i.id].kwh !== null) todayTotal += D[i.id].kwh;
        else allReady = false;
        if (D[i.id].kwhYday !== undefined && D[i.id].kwhYday !== null) ydayTotal += D[i.id].kwhYday;
        else allReady = false;
      });
      if (!allReady || ydayTotal === 0) return;
      var pct = ((todayTotal - ydayTotal) / ydayTotal * 100);
      var up = pct >= 0;
      var col = up ? '#EF4444' : '#10B981';
      var trendEl = el('cr-trend-' + c.id);
      var trendLbl = document.querySelector('#cl-' + c.id + ' .cr-trend-lbl');
      if (trendEl) {
        trendEl.textContent = (up ? '↑ +' : '↓ ') + Math.abs(pct).toFixed(1) + '%';
        trendEl.style.color = col;
      }
      if (trendLbl) trendLbl.style.color = '#96AABF';
    });
  }

  function loadSparkline(inst) {
    var key=inst.type==='piscina'?flota(inst).temp:flota(inst).kw;
    api(tsUrl(inst.deviceId,key,daysAgo(0.5),nowMs(),3600000,'AVG',12),
      function(d){
        var pts=(d[key]||[]).map(function(p){return parseFloat(p.value);});
        if(pts.length<2) return;
        D[inst.id].sparkData=pts;
        var sp=el('ic-sp-'+inst.id);
        if(sp) sp.innerHTML=buildSpark(pts,'#00EBC8');
      });
  }

  /* ── UPDATE CARD DOM ────────────────────────────────────── */
  function updateInstCard(inst) {
    var isPisc=inst.type==='piscina';
    /* Main KPI */
    var big=el('ic-big-'+inst.id);
    if(big){
      if(isPisc&&D[inst.id].temp!==null) big.textContent=fmtT(D[inst.id].temp);
      else if(!isPisc&&D[inst.id].kw!==null) big.textContent=D[inst.id].kw.toFixed(1);
      else big.textContent='—';
    }
    /* Secondary */
    var s1=el('ic-s1-'+inst.id), s2=el('ic-s2-'+inst.id);
    if(isPisc){
      if(s1) s1.textContent=D[inst.id].calOn!==null?(D[inst.id].calOn?'Encendido':'Apagado'):'—';
      if(s2) s2.textContent=D[inst.id].temp!==null?fmtT(D[inst.id].temp)+'°C':'—';
    } else {
      if(s1) s1.textContent=D[inst.id].kwh!==null?D[inst.id].kwh.toFixed(1)+' kWh':'—';
      if(s2) s2.textContent=D[inst.id].fp!==null?D[inst.id].fp.toFixed(2):'—';
    }
    /* Last seen */
    var last=el('ic-last-'+inst.id);
    if(last) last.textContent=D[inst.id].lastTs?timeSince(D[inst.id].lastTs):({sin:'Sin datos',nd:'No disponible'}[D[inst.id].lectura]||'Cargando…');   /* R1 */
  }

  /* ── AGGREGATE UPDATER ──────────────────────────────────── */
  function updateAggregates() {
    if(currentLayer===0) updateLayer0Aggregates();
    else                 updateLayer1Aggregates(instsDe(selectedClient));
  }

  /* ── REFRESH TIMER ──────────────────────────────────────── */
  var timer=setInterval(function(){
    scopeInsts().filter(consultable).forEach(function(inst){   /* R1: sin los dispositivos con 404/403 */
      if(inst.type==='3em') load3EMLatest(inst);
      else                  loadPiscLatest(inst);
    });
  },30000);

  self.onDestroy=function(){clearInterval(timer);};
  self.onResize  = function () { applyLayout(); };
};

